Since the edge weights are non-negative, a min-heap can always choose the node with the smallest known distance. Stale heap entries are skipped because a node may be inserted again after a shorter route is found.

This is not as fast as using the DAG order, but it is a familiar shortest path implementation. The edge list remains unchanged.

```cpp
#include <vector>
#include <queue>
#include <climits>
using namespace std;

class Solution {
public:
    vector < int > shortestPath(int N, int M, vector < vector < int >> & edges) {
        vector<vector<pair<int, int>>> graph(N);

        for (const auto& edge : edges) {
            graph[edge[0]].push_back({edge[1], edge[2]});
        }

        const int INF = INT_MAX / 4;
        vector<int> distance(N, INF);
        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> heap;

        distance[0] = 0;
        heap.push({0, 0});

        while (!heap.empty()) {
            int currentDistance = heap.top().first;
            int node = heap.top().second;
            heap.pop();

            if (currentDistance != distance[node]) {
                continue;
            }

            for (const auto& edge : graph[node]) {
                int nextNode = edge.first;
                int weight = edge.second;
                int candidate = currentDistance + weight;

                if (candidate < distance[nextNode]) {
                    distance[nextNode] = candidate;
                    heap.push({candidate, nextNode});
                }
            }
        }

        for (int& value : distance) {
            if (value == INF) {
                value = -1;
            }
        }

        return distance;
    }
};
```

One important limitation is that this heap method needs non-negative weights. The usual DAG solution can support negative weights, but Dijkstra's method cannot.

Time complexity: `O((N + M) log N)`.
Space complexity: `O(N + M)`.

Here the shortest distance from a node means the best cost from that node to the final reachable part of the graph. A small DFS helper stores the best known distance from source `0` to each node, so each node is expanded only once.

The graph is a DAG, which is important because recursion cannot safely use this memo rule on a graph with cycles. Unreachable nodes are returned as `-1`.

```java
import java.util.*;

class Solution {
    private void relaxFrom(int node, int distanceSoFar,
                           List<List<int[]>> graph, int[] distance) {
        if (distanceSoFar >= distance[node]) {
            return;
        }

        distance[node] = distanceSoFar;

        for (int[] edge : graph.get(node)) {
            relaxFrom(edge[0], distanceSoFar + edge[1], graph, distance);
        }
    }

    public int[] shortestPath(int N, int M, int[][] edges) {
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            graph.get(edge[0]).add(new int[]{edge[1], edge[2]});
        }

        int inf = Integer.MAX_VALUE / 4;
        int[] distance = new int[N];
        Arrays.fill(distance, inf);
        distance[0] = 0;

        relaxFrom(0, 0, graph, distance);

        for (int i = 0; i < N; i++) {
            if (distance[i] == inf) {
                distance[i] = -1;
            }
        }

        return distance;
    }
}
```

For an edge from `0` to `1` with weight `4`, the helper stores `distance[1] = 4`. If another route reaches `1` with a smaller value, the recursive call updates it. The early return avoids expanding a node when the new route is not better.

This style is short, but a very deep DAG can make the recursion stack large. It also assumes the edge weights are non-negative for the pruning check to stay safe.

Time complexity: up to `O(N + M)` for the usual non-negative DAG inputs.
Space complexity: `O(N + M)` for the graph and recursion stack.

This version builds the graph and uses DFS to create a topological order. After reversing the finishing order, every edge goes from an earlier node to a later node, so distances can be relaxed once in that order.

A node can be unreachable from `0`, so its distance stays at a large value and is converted to `-1`. The input edge list is not changed.

```java
import java.util.*;

class Solution {
    private void buildOrder(int node, boolean[] visited,
                            List<List<int[]>> graph, List<Integer> order) {
        visited[node] = true;

        for (int[] edge : graph.get(node)) {
            if (!visited[edge[0]]) {
                buildOrder(edge[0], visited, graph, order);
            }
        }

        order.add(node);
    }

    public int[] shortestPath(int N, int M, int[][] edges) {
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            graph.get(edge[0]).add(new int[]{edge[1], edge[2]});
        }

        boolean[] visited = new boolean[N];
        List<Integer> order = new ArrayList<>();
        for (int node = 0; node < N; node++) {
            if (!visited[node]) {
                buildOrder(node, visited, graph, order);
            }
        }
        Collections.reverse(order);

        int inf = Integer.MAX_VALUE / 4;
        int[] distance = new int[N];
        Arrays.fill(distance, inf);
        distance[0] = 0;

        for (int node : order) {
            if (distance[node] == inf) {
                continue;
            }

            for (int[] edge : graph.get(node)) {
                int nextNode = edge[0];
                int weight = edge[1];
                distance[nextNode] = Math.min(
                    distance[nextNode], distance[node] + weight
                );
            }
        }

        for (int i = 0; i < N; i++) {
            if (distance[i] == inf) {
                distance[i] = -1;
            }
        }

        return distance;
    }
}
```

Dry run: for edges `0 -> 1 (2)` and `1 -> 2 (3)`, the distances start as `[0, inf, inf]`. Processing node `0` gives node `1` distance `2`, then node `1` gives node `2` distance `5`.

Time complexity: `O(N + M)`.
Space complexity: `O(N + M)`, plus the recursion stack.

A queue-based topological sort keeps the order simple. First, the indegree of every node is counted. Nodes with indegree zero are processed, and relaxing their outgoing edges can unlock the next nodes.

The distance starts at node `0`. An unreachable node is left as infinity and changed to `-1` at the end.

```cpp
#include <vector>
#include <queue>
#include <climits>
using namespace std;

class Solution {
public:
    vector < int > shortestPath(int N, int M, vector < vector < int >> & edges) {
        vector<vector<pair<int, int>>> graph(N);
        vector<int> indegree(N, 0);

        for (const auto& edge : edges) {
            int from = edge[0];
            int to = edge[1];
            int weight = edge[2];
            graph[from].push_back({to, weight});
            indegree[to]++;
        }

        queue<int> ready;
        for (int node = 0; node < N; node++) {
            if (indegree[node] == 0) {
                ready.push(node);
            }
        }

        const int INF = INT_MAX / 4;
        vector<int> distance(N, INF);
        distance[0] = 0;

        while (!ready.empty()) {
            int node = ready.front();
            ready.pop();

            for (const auto& next : graph[node]) {
                int nextNode = next.first;
                int weight = next.second;

                if (distance[node] != INF) {
                    distance[nextNode] = min(distance[nextNode], distance[node] + weight);
                }

                indegree[nextNode]--;
                if (indegree[nextNode] == 0) {
                    ready.push(nextNode);
                }
            }
        }

        for (int& value : distance) {
            if (value == INF) {
                value = -1;
            }
        }

        return distance;
    }
};
```

For example, if node `0` reaches node `2` with cost `4`, then `distance[2]` becomes `4`. A later route can replace it only when that route is smaller.

Time complexity: `O(N + M)`.
Space complexity: `O(N + M)`.

